 entries=git('ls-tree','-rz',rev+':'+base+'/'+part).split(b'\0');items=[]
 for item in entries:
  if not item:continue
  desc,name=item.split(b'\t',1);mode,kind,oid=desc.split();assert kind==b'blob';items.append((name.decode(),oid.decode()))
 raw=git('cat-file','--batch',input=''.join(oid+'\n' for _,oid in items).encode());cursor=0;contents={}
 for name,oid in items:
  end=raw.index(b'\n',cursor);head=raw[cursor:end].split();assert head[0].decode()==oid and head[1]==b'blob';n=int(head[2]);start=end+1;contents[name]=raw[start:start+n];cursor=start+n+1
 assert cursor==len(raw)
 return contents
